import{_ as s,o as i,c as t,a2 as o}from"./chunks/framework.C_fNVUec.js";const u=JSON.parse('{"title":"Live agent sessions","description":"","frontmatter":{},"headers":[],"relativePath":"docs/live-sessions.md","filePath":"docs/live-sessions.md","lastUpdated":1793898059000}'),a={name:"docs/live-sessions.md"};function n(r,e,d,l,c,p){return i(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="live-agent-sessions" tabindex="-1">Live agent sessions <a class="header-anchor" href="#live-agent-sessions" aria-label="Permalink to &quot;Live agent sessions&quot;">​</a></h1><p>The Sessions view uses the same working, waiting and ended states, task links, search and conversation viewer for all agents. Waiting sessions stay in the active view; inactivity alone does not end a registered session.</p><p>Codex uses its native writer locks and latest turn status. A held lock identifies an open session; a completed turn is waiting, and a turn in progress is working. A released lock ends the session. Older Codex versions without a writer-lock directory retain the legacy activity fallback.</p><p>Cursor IDE history, Cursor CLI (<code>agent</code> / <code>cursor-agent</code>) history and Gemini conversations are discovered separately. CLI and IDE Cursor histories are separate stores: only Cursor CLI records offer a CLI resume command. Gemini and Cursor CLI support Resume in a terminal, Copy resume command, and Copy terminal link alongside Claude and Codex.</p><p>Install lifecycle hooks for Cursor and Gemini from this checkout:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">bun scripts</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">install-session</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">hooks.ts</span></span></code></pre></div><p>The installer preserves existing hook entries and other settings, makes dated backups, and adds lifecycle events to <code>~/.cursor/hooks.json</code> and <code>~/.gemini/settings.json</code>. New/resumed sessions register their owner PID in <code>~/.orc/live-sessions/</code>. Start, prompt, response, tool and stop hooks update the shared state; session-end hooks and dead owner processes end it. Existing sessions may need to resume or reload hooks once before they register. Hook-captured conversations begin when hooks are installed; old native history is retained when its transcript exists.</p><p>Hooks need Bun on the installation machine. They run a bounded owner lookup, write private local registry/transcript files, and never grant tool permissions or inject prompts. Native agent transcripts remain read-only. Full prompt/tool content belongs to the local conversation history and is not sent to external services by these hooks.</p><p>Other local agents can use <code>LiveRegistration</code>, <code>readRegistrations</code> and <code>writeRegistration</code> from <code>@orc/core/live-session</code> to participate in the same PID-backed lifecycle. Native discovery/resume commands still require a supported adapter; the dashboard automatically includes registered backend names in its filter.</p>',9)])])}const k=s(a,[["render",n]]);export{u as __pageData,k as default};
